q=[('cosmos-kosmoport-2626','Космопорт — линейка «Космос»',2626,'q_spaceadv_36',{'Контекст':'Старзи рассказывает, что для Машины времени нужны специальные запчасти. Задание на Звёздном перевале.','Цели':'Начать строить Космопорт; разослать всем друзьям любой бесплатный подарок с сообщением «Выход есть всегда!». Вторую цель можно пропустить за 25 зб.','Неясное значение':'Между целями в источнике приведена отдельная ссылка с числом 100; её смысл по тексту не установлен.','Награда':'1 «Минутка на день».','Соседние задания':'Предыдущее — «Подробности» (№2625), следующее — «Усилитель» (№2627).'}),('cosmos-usilitel-2627','Усилитель — линейка «Космос»',2627,'q_spaceadv_37',{'Контекст':'Старзи говорит, что Усилитель находится среди обломков спутника на Туманном. Задание острова Звёздный перевал.','Цели':'Достроить Космопорт; отправиться на Туманный из Космопорта.','Награда':'45 ножей.','Соседние задания':'Предыдущее — «Космопорт» (№2626), следующее — «Поиски» (№2628).','Преобразование объектов':'В разделе о преобразовании после выполнения перечислены «Космопорт» и «Сокровища»; направление преобразования в текстовом представлении неясно.'}),('cosmos-po-planu-2629','По плану — линейка «Космос»',2629,'q_spaceadv_39',{'Контекст':'Старзи упоминает следующую деталь на Зомбикроне и Жёлтую будку; в диалоге Зомби сомневается, что они на Зомбикроне. Задание острова Туманный.','Цели':'Найти и построить Жёлтую будку на Туманном астероиде; телепортироваться с Туманного.','Награда':'1 Бочка повара.','Соседние задания':'Предыдущее — «Поиски» (№2628), следующее — «Ниже нуля» (№2630).','Примечание':'В диалоге упомянут Зомбикрон, но статья Жёлтой будки №824 указывает фактическим направлением Комету; не приравниваем сюжетную реплику к маршруту.'})]
