  n=2 if cat=='buildings' else 11;part='building' if cat=='buildings' else 'gamemission';url=f'https://viver.my1.ru/publ/{part}/{path}/{n}-1-0-{id}';r={'original_id':f'viver-{cat}-{id}','original_category':orig,'version':'историческая социальная версия VK; дата редакции неизвестна','date':date+' — публикация, дата последующей редакции неизвестна','fields':fields,'confidence':'Фанатский справочник; актуальность и независимость не установлены.'};e['prior_records']=[r0 for r0 in e.get('prior_records',[]) if r0.get('original_id')!=r['original_id']]+[r]
